<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,reactive,ref,watch} from 'vue';
import Icon from './Icon.vue';import CustomerPicker from './CustomerPicker.vue';import {cents,scaled,quoteLineAmount} from './commerceAmounts';
type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
type Item={id:string;[key:string]:any};type Access={productRead:boolean;productWrite:boolean;quotes:{read:boolean;write:boolean};pdfExport:boolean;approve:boolean};
const props=withDefaults(defineProps<{section:string;request:Request;download:(path:string,name:string)=>Promise<void>;access:Access;readonly:boolean;customerWrite:boolean;opportunityRead:boolean;contractWrite:boolean;customerId?:string}>(),{customerId:''});
const emit=defineEmits<{customer:[id:string];clearFilter:[];contract:[id:string]}>();
const busy=ref(false),error=ref(''),success=ref(''),items=ref<Item[]>([]),page=ref(1),total=ref(0),search=ref(''),state=ref('');
const dialog=ref(''),modal=ref<HTMLElement|null>(null),selected=ref<Item|null>(null),snapshot=ref<any>(null),requestKey=ref(''),history=ref<Item[]>([]),historyPage=ref(1),historyTotal=ref(0),voidReason=ref('');
const product=reactive({sku:'',name:'',kind:'PRODUCT',unit:'件',price:'0.00',description:'',status:'ACTIVE'});
type Line={id?:string;productId:string;name:string;sku:string;unit:string;quantity:string;price:string;discount:string;description:string};
const quote=reactive({title:'',customerId:'',customerName:'',opportunityId:'',validUntil:'',notes:'',lines:[] as Line[]});
const catalog=ref<Item[]>([]),catalogQuery=ref(''),catalogPage=ref(1),catalogTotal=ref(0),chosenProduct=ref('');
const opportunities=ref<Item[]>([]),opQuery=ref(''),opPage=ref(1),opTotal=ref(0);
const approvalRows=ref<Item[]>([]),approvalPage=ref(1),approvalTotal=ref(0),approvers=ref<Item[]>([]),approverPage=ref(1),approverTotal=ref(0),approverQuery=ref(''),approverId=ref(''),decisionReason=ref(''),changeReason=ref('');
const statusNames:Record<string,string>={DRAFT:'草稿',SUBMITTED:'待审批',APPROVED:'已批准',REJECTED:'已驳回',PENDING:'待审批',WITHDRAWN:'已撤回',VOID:'已作废',ACTIVE:'启用',INACTIVE:'停用'};
const actionNames:Record<string,string>={CREATED:'创建草稿',UPDATED:'修改草稿',SUBMIT:'提交',WITHDRAW:'撤回',VOID:'作废',APPROVED:'批准',REJECTED:'驳回',REVISE:'转回草稿'};
const approvalMode=computed(()=>props.section==='quote-approvals'),productMode=computed(()=>props.section==='products'),historical=computed(()=>snapshot.value&&selected.value&&snapshot.value.version!==selected.value.version);
const quoteWritable=computed(()=>props.access.quotes.write&&props.access.productRead&&props.customerWrite&&!props.readonly);
const totalPreview=computed(()=>{try{let n=0;for(const l of quote.lines)n+=quoteLineAmount(l.quantity,l.price,l.discount);if(n>100000000000)throw new Error('报价总额超过上限');return {value:n,error:''};}catch(e){return{value:0,error:(e as Error).message};}});
const money=(value:number)=>'¥'+(value/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const date=(v:string)=>v?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'—';
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){const f=e as Error&{status?:number};error.value=f.message||'操作未完成';if([401,403,404].includes(f.status??0)){dialog.value='';items.value=[];selected.value=null;snapshot.value=null;}}finally{busy.value=false;}}
async function load(){const r=await props.request<any>(`/${productMode.value?'products':'quotes'}?mine=${approvalMode.value}&page=${page.value}&pageSize=20&q=${encodeURIComponent(search.value)}&status=${state.value}${!productMode.value&&props.customerId?'&customerId='+props.customerId:''}`);items.value=r.items;total.value=r.total;}
function searchItems(){page.value=1;return run(load);}function turn(delta:number){page.value+=delta;return run(load);}
function openProduct(item?:Item){selected.value=item??null;Object.assign(product,item?{...item,price:(item.priceCents/100).toFixed(2)}:{sku:'',name:'',kind:'PRODUCT',unit:'件',price:'0.00',description:'',status:'ACTIVE'});requestKey.value=crypto.randomUUID();dialog.value='product';}
function saveProduct(){return run(async()=>{const data={sku:product.sku,name:product.name,kind:product.kind,unit:product.unit,priceCents:cents(product.price),description:product.description,status:product.status,expectedVersion:selected.value?.version??0};await props.request(selected.value?'/products/'+selected.value.id:'/products',selected.value?'PUT':'POST',data,selected.value?{}:{'Idempotency-Key':requestKey.value});dialog.value='';await load();success.value='产品目录已保存；历史报价的名称和价格快照保持原记录';});}
async function catalogLoad(){const r=await props.request<any>(`/products?page=${catalogPage.value}&pageSize=20&status=ACTIVE&q=${encodeURIComponent(catalogQuery.value)}`);catalog.value=r.items;catalogTotal.value=r.total;}
function catalogSearch(){catalogPage.value=1;return run(catalogLoad);}function catalogTurn(d:number){catalogPage.value+=d;return run(catalogLoad);}
async function opLoad(){opportunities.value=[];opTotal.value=0;if(!quote.customerId||!props.opportunityRead)return;const r=await props.request<any>(`/opportunities?customerId=${quote.customerId}&page=${opPage.value}&pageSize=20&q=${encodeURIComponent(opQuery.value)}`);opportunities.value=r.items.filter((o:Item)=>o.canLink);opTotal.value=r.total;}
function customerChanged(id:string){quote.customerId=id;quote.opportunityId='';opPage.value=1;run(opLoad);}function opSearch(){opPage.value=1;run(opLoad);}function opTurn(d:number){opPage.value+=d;run(opLoad);}
function addLine(){const p=catalog.value.find(p=>p.id===chosenProduct.value);if(!p)return;if(quote.lines.length>=100){error.value='每份报价最多100行';return;}quote.lines.push({productId:p.id,name:p.name,sku:p.sku,unit:p.unit,quantity:'1',price:(p.priceCents/100).toFixed(2),discount:'0',description:''});chosenProduct.value='';}
function openQuote(item?:Item){return run(async()=>{selected.value=item?await props.request<Item>('/quotes/'+item.id):null;const q=selected.value;Object.assign(quote,q?{title:q.title,customerId:q.customerId,customerName:q.customerNameSnapshot,opportunityId:q.opportunityId??'',validUntil:q.validUntil,notes:q.notes,lines:q.lines.map((l:any)=>({id:l.id,productId:l.productId,name:l.nameSnapshot,sku:l.skuSnapshot,unit:l.unitSnapshot,quantity:String(l.quantity),price:(l.unitPriceCents/100).toFixed(2),discount:(l.discountBps/100).toFixed(2),description:l.description}))}:{title:'',customerId:props.customerId,customerName:'',opportunityId:'',validUntil:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date(Date.now()+30*86400000)),notes:'',lines:[]});if(!q&&props.customerId)quote.customerName=(await props.request<any>('/customers/'+props.customerId)).name;catalogQuery.value='';catalogPage.value=1;chosenProduct.value='';opQuery.value='';opPage.value=1;requestKey.value=crypto.randomUUID();dialog.value='quote-edit';await catalogLoad();if(!q)await opLoad();});}
function saveQuote(){return run(async()=>{if(!quote.lines.length)throw new Error('请至少添加一行产品或服务');if(totalPreview.value.error)throw new Error(totalPreview.value.error);const data={customerId:quote.customerId,opportunityId:quote.opportunityId||null,title:quote.title,validUntil:quote.validUntil,notes:quote.notes,expectedVersion:selected.value?.version??0,lines:quote.lines.map(l=>({id:l.id??null,productId:l.productId,quantity:l.quantity,unitPriceCents:cents(l.price),discountBps:Number(scaled(l.discount,2)),description:l.description}))};await props.request(selected.value?'/quotes/'+selected.value.id:'/quotes',selected.value?'PUT':'POST',data,selected.value?{}:{'Idempotency-Key':requestKey.value});dialog.value='';await load();success.value='报价草稿已保存，服务器已计算含税金额';});}
async function historyLoad(){const r=await props.request<any>(`/quotes/${selected.value!.id}/history?page=${historyPage.value}&pageSize=20`);history.value=r.items;historyTotal.value=r.total;}
function show(item:Item){return run(async()=>{selected.value=await props.request<Item>('/quotes/'+item.id);snapshot.value=selected.value;historyPage.value=1;voidReason.value='';decisionReason.value='';changeReason.value='';approverId.value='';approverQuery.value='';approverPage.value=1;approvalPage.value=1;await historyLoad();await approvalLoad();if(selected.value!.canManage&&!props.readonly&&['DRAFT','REJECTED'].includes(selected.value!.status))await approversLoad();dialog.value='quote-view';});}
function selectVersion(version:number){return run(async()=>{snapshot.value=version===selected.value?.version?selected.value:await props.request('/quotes/'+selected.value!.id+'/versions/'+version);});}
function historyTurn(d:number){historyPage.value+=d;run(historyLoad);}
async function approvalLoad(){const r=await props.request<any>(`/quotes/${selected.value!.id}/approvals?page=${approvalPage.value}&pageSize=10`);approvalRows.value=r.items;approvalTotal.value=r.total;}
function approvalTurn(d:number){approvalPage.value+=d;return run(approvalLoad);}
async function approversLoad(){const r=await props.request<any>(`/quotes/${selected.value!.id}/approvers?page=${approverPage.value}&pageSize=20&q=${encodeURIComponent(approverQuery.value)}`);approvers.value=r.items;approverTotal.value=r.total;}
function approverSearch(){approverPage.value=1;return run(approversLoad);}function approverTurn(d:number){approverPage.value+=d;return run(approversLoad);}
function decide(action:string){return run(async()=>{const q=selected.value;if(!q?.approval)throw new Error('当前没有可处理的审批');selected.value=await props.request<Item>(`/quotes/${q.id}/approval/${action}`,'POST',{approvalId:q.approval.id,expectedVersion:q.version,reason:decisionReason.value},{'Idempotency-Key':q.approval.id+':'+action});snapshot.value=selected.value;await historyLoad();await approvalLoad();await load();success.value=action==='approve'?'已批准该版本，后续修改需要重新审批':'已驳回并记录原因，报价人可修改后重新提交';});}
function transition(action:string){return run(async()=>{if(!selected.value)return;const q=selected.value;selected.value=await props.request<Item>(`/quotes/${q.id}/${action}`,'POST',{expectedVersion:q.version,reason:action==='void'?voidReason.value:action==='revise'?changeReason.value:'',approverMemberId:action==='submit'?approverId.value:null},{'Idempotency-Key':q.id+':'+q.version+':'+action});snapshot.value=selected.value;await historyLoad();await approvalLoad();if(['DRAFT','REJECTED'].includes(selected.value!.status))await approversLoad();await load();success.value=action==='submit'?'已提交给指定销售经理审批并锁定明细':action==='withdraw'?'已撤回，原审批已取消':action==='revise'?'已转回草稿，原批准不再用于当前报价，修改后需重新提交':'已作废并保留历史记录';});}
function exportPdf(){return run(async()=>{await props.download(`/quotes/${selected.value!.id}/pdf?version=${snapshot.value.version}`,snapshot.value.quoteNumber+'-v'+snapshot.value.version+'.pdf');success.value='已下载指定版本的报价 PDF';});}
let previousFocus:HTMLElement|null=null,previousOverflow='';watch(dialog,async(value,old)=>{if(value&&!old){previousFocus=document.activeElement as HTMLElement;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';}if(value){await nextTick();modal.value?.querySelector<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled)')?.focus({preventScroll:true});}else{document.body.style.overflow=previousOverflow;previousFocus?.focus({preventScroll:true});}});
function keys(e:KeyboardEvent){if(!dialog.value)return;if(e.key==='Escape'&&!busy.value)dialog.value='';if(e.key==='Tab'){const nodes=modal.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
onMounted(()=>{document.addEventListener('keydown',keys);run(load);});onUnmounted(()=>{document.removeEventListener('keydown',keys);if(dialog.value)document.body.style.overflow=previousOverflow;});
</script>
<template>
 <section class="commerce"><div class="page-heading"><div><span class="eyebrow">PRODUCTS & QUOTES</span><h1>{{productMode?'产品与服务目录':approvalMode?'待我审批的报价':'客户报价'}}</h1><p>{{productMode?'统一维护含税价目，停用产品会保留历史报价。':'从客户需求形成报价，保留版本、明细和销售依据。'}}</p></div><button class="btn secondary" :disabled="busy" @click="run(load)">刷新</button><button v-if="!approvalMode&&(productMode?access.productWrite&&!readonly:quoteWritable)" class="btn primary" :disabled="busy" @click="productMode?openProduct():openQuote()">{{productMode?'新增产品 / 服务':'新建报价'}}</button></div>
 <div v-if="error" class="commerce-alert error" role="alert">{{error}}</div><div v-if="success" class="commerce-alert ok" role="status">{{success}}</div><div v-if="readonly" class="commerce-alert">企业当前只允许查看，业务写入已关闭。</div>
 <div class="card commerce-toolbar"><input v-model="search" type="search" maxlength="100" :placeholder="productMode?'搜索编码、名称':'搜索报价编号、主题、客户'" aria-label="搜索目录或报价" @keydown.enter="searchItems"/><select v-model="state" aria-label="筛选状态" @change="searchItems"><option value="">全部状态</option><option v-for="s in productMode?['ACTIVE','INACTIVE']:['DRAFT','SUBMITTED','APPROVED','REJECTED','VOID']" :key="s" :value="s">{{statusNames[s]}}</option></select><button class="btn secondary" :disabled="busy" @click="searchItems">查询</button><button v-if="customerId" class="text-button" @click="emit('clearFilter')">清除客户筛选</button></div>
 <section class="card commerce-block"><p v-if="!productMode" class="commerce-muted">含税人民币报价；提交后锁定明细。提交时指定另一位有资料权限的销售经理；批准后修改需要重新审批。</p><div class="table-scroll"><table><thead><tr><th>{{productMode?'产品编码 / 名称':'报价编号 / 主题'}}</th><th>{{productMode?'类型 / 单位':'客户 / 报价人'}}</th><th>{{productMode?'含税单价':'含税总额'}}</th><th>状态</th><th>{{productMode?'版本':'有效期 / 版本'}}</th><th>操作</th></tr></thead><tbody><tr v-for="r in items" :key="r.id"><td><strong>{{productMode?r.name:r.title}}</strong><small>{{productMode?r.sku:r.quoteNumber}}</small></td><td>{{productMode?(r.kind==='SERVICE'?'服务':'产品')+' / '+r.unit:r.customerNameSnapshot}}<small v-if="!productMode">{{r.ownerNameSnapshot}}</small></td><td>{{money(productMode?r.priceCents:r.totalCents)}}</td><td><span class="badge" :class="['ACTIVE','SUBMITTED'].includes(r.status)?'green':'neutral'">{{statusNames[r.status]}}</span></td><td>{{productMode?'v'+r.version:r.validUntil}}<small v-if="!productMode">v{{r.version}}</small></td><td><button v-if="productMode" class="text-button" :disabled="busy" @click="openProduct(r)">{{access.productWrite&&!readonly?'查看 / 编辑':'查看'}}</button><template v-else><button class="text-button" :disabled="busy" @click="show(r)">查看 / 版本</button><button v-if="!approvalMode&&r.canWrite&&quoteWritable" class="text-button" :disabled="busy" @click="openQuote(r)">编辑草稿</button></template></td></tr><tr v-if="!items.length"><td colspan="6" class="empty-cell">{{busy?'正在加载…':productMode?'暂无产品，可由销售经理维护价目目录':'暂无可见报价，可从客户创建第一份草稿'}}</td></tr></tbody></table></div><div class="commerce-pages"><span>共 {{total}} 条 · 第 {{page}} 页</span><button class="btn secondary" :disabled="busy||page<=1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="busy||page*20>=total" @click="turn(1)">下一页</button></div></section>
 <Teleport to="body"><div v-if="dialog" class="commerce-backdrop" @click.self="!busy&&(dialog='')"><section ref="modal" class="commerce-dialog" role="dialog" aria-modal="true" aria-labelledby="commerce-title"><header><h2 id="commerce-title">{{dialog==='product'?'产品 / 服务资料':dialog==='quote-edit'?'编辑报价草稿':'报价明细与版本'}}</h2><button class="icon-button" aria-label="关闭弹窗" :disabled="busy" @click="dialog=''"><Icon name="close"/></button></header><div v-if="error" class="commerce-alert error" role="alert">{{error}}</div>
 <form v-if="dialog==='product'" @submit.prevent="saveProduct"><div class="commerce-body"><fieldset class="commerce-fields" :disabled="busy||readonly||!access.productWrite"><label>产品编码<input v-model="product.sku" required maxlength="40" pattern="[A-Za-z0-9_.-]+"/><small>字母、数字、点、下划线或短横线，企业内唯一</small></label><label>名称<input v-model="product.name" required maxlength="120"/></label><label>类型<select v-model="product.kind"><option value="PRODUCT">产品</option><option value="SERVICE">服务</option></select></label><label>计价单位<input v-model="product.unit" required maxlength="20"/></label><label>含税单价（元）<input v-model="product.price" required maxlength="13" inputmode="decimal"/></label><label>状态<select v-model="product.status"><option value="ACTIVE">启用</option><option value="INACTIVE">停用</option></select></label><label class="wide">说明<textarea v-model="product.description" maxlength="1000" rows="4"/></label></fieldset></div><footer><button type="button" class="btn secondary" :disabled="busy" @click="dialog=''">关闭</button><button v-if="access.productWrite&&!readonly" class="btn primary" :disabled="busy">保存目录</button></footer></form>
 <form v-else-if="dialog==='quote-edit'" @submit.prevent="saveQuote"><div class="commerce-body"><fieldset class="commerce-fields" :disabled="busy||!quoteWritable"><label class="wide">报价主题<input v-model="quote.title" required maxlength="200"/></label><label class="wide">所属客户<CustomerPicker :model-value="quote.customerId" :selected-name="quote.customerName" :request="request" :disabled="!!selected||busy" @update:model-value="customerChanged"/></label><label class="wide">关联商机（选填）<template v-if="!selected&&opportunityRead"><div class="commerce-inline"><input v-model="opQuery" placeholder="查找当前客户的商机" aria-label="查找关联商机" @keydown.enter.prevent="opSearch"/><button type="button" class="btn secondary" @click="opSearch">查找</button></div><select v-model="quote.opportunityId"><option value="">不关联商机</option><option v-for="o in opportunities" :key="o.id" :value="o.id">{{o.title}}</option></select><div class="commerce-inline"><button type="button" :disabled="opPage<=1" @click="opTurn(-1)">上一页</button><small>第 {{opPage}} 页</small><button type="button" :disabled="opPage*20>=opTotal" @click="opTurn(1)">下一页</button></div></template><span v-else>{{selected?.opportunityTitleSnapshot||'不关联商机'}}</span></label><label>有效期<input v-model="quote.validUntil" type="date" required min="2000-01-01" max="2100-12-31"/></label><label class="wide">报价说明<textarea v-model="quote.notes" rows="3" maxlength="4000"/></label></fieldset>
 <h3>报价明细 <small>最多 100 行，折扣填写优惠百分比，例如 10 表示减价 10%</small></h3><div class="commerce-catalog"><div class="commerce-inline"><input v-model="catalogQuery" maxlength="100" placeholder="搜索启用的产品 / 服务" aria-label="搜索报价产品" @keydown.enter.prevent="catalogSearch"/><button type="button" class="btn secondary" :disabled="busy" @click="catalogSearch">查找</button></div><div class="commerce-inline"><select v-model="chosenProduct" aria-label="选择加入报价的产品"><option value="">选择产品 / 服务</option><option v-for="p in catalog" :key="p.id" :value="p.id">{{p.sku}} · {{p.name}} · {{money(p.priceCents)}} / {{p.unit}}</option></select><button type="button" class="btn secondary" :disabled="busy||!chosenProduct||quote.lines.length>=100" @click="addLine">添加一行</button></div><div class="commerce-inline"><button type="button" :disabled="busy||catalogPage<=1" @click="catalogTurn(-1)">上一页</button><small>产品第 {{catalogPage}} 页 · 共 {{catalogTotal}} 条</small><button type="button" :disabled="busy||catalogPage*20>=catalogTotal" @click="catalogTurn(1)">下一页</button></div></div>
 <article v-for="(l,i) in quote.lines" :key="l.id??i" class="commerce-line"><div><strong>{{i+1}}. {{l.name}}</strong><small>{{l.sku}} · {{l.unit}} · 保存名称快照</small><button type="button" class="text-button" :disabled="busy" @click="quote.lines.splice(i,1)">移除这一行</button></div><div class="commerce-fields"><label>数量<input v-model="l.quantity" required maxlength="12" inputmode="decimal"/></label><label>含税单价（元）<input v-model="l.price" required maxlength="13" inputmode="decimal"/></label><label>折扣（%）<input v-model="l.discount" required maxlength="6" inputmode="decimal"/></label><label class="wide">行说明<input v-model="l.description" maxlength="300"/></label></div></article><p v-if="!quote.lines.length" class="commerce-muted">从目录选择产品，添加到报价中。</p><p v-if="totalPreview.error" class="commerce-alert error">{{totalPreview.error}}</p><div class="commerce-total">含税总额预览 <strong>{{money(totalPreview.value)}}</strong><small>逐行四舍五入到分；保存时服务器重新核算。</small></div></div><footer><button type="button" class="btn secondary" :disabled="busy" @click="dialog=''">取消</button><button class="btn primary" :disabled="busy||!quoteWritable||!quote.lines.length||!!totalPreview.error">保存草稿</button></footer></form>
 <template v-else-if="snapshot"><div class="commerce-body"><div class="commerce-detail-heading"><strong>{{snapshot.quoteNumber}} · v{{snapshot.version}}</strong><span class="badge neutral">{{statusNames[snapshot.status]}}{{historical?' · 历史版本':''}}</span></div><h3>{{snapshot.title}}</h3><p>{{snapshot.companyNameSnapshot}} → {{snapshot.customerNameSnapshot}}</p><p class="commerce-muted">报价人 {{snapshot.ownerNameSnapshot}} · 有效期 {{snapshot.validUntil}} · {{snapshot.opportunityTitleSnapshot||'未关联商机'}}</p><p v-if="snapshot.validUntil<new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date())" class="commerce-alert">该版本报价已过期。</p><div class="table-scroll"><table><thead><tr><th>产品 / 服务快照</th><th>数量</th><th>含税单价</th><th>折扣</th><th>含税金额</th></tr></thead><tbody><tr v-for="l in snapshot.lines" :key="l.id"><td>{{l.nameSnapshot}}<small>{{l.skuSnapshot}} · {{l.unitSnapshot}}</small><small>{{l.description}}</small></td><td>{{l.quantity}}</td><td>{{money(l.unitPriceCents)}}</td><td>{{l.discountBps/100}}%</td><td>{{money(l.amountCents)}}</td></tr></tbody></table></div><div class="commerce-total"><strong>含税总额 {{money(snapshot.totalCents)}}</strong></div><p class="commerce-notes">{{snapshot.notes}}</p><p v-if="snapshot.voidReason" class="commerce-alert">作废原因：{{snapshot.voidReason}}</p><div v-if="!historical&&snapshot.status==='APPROVED'&&contractWrite&&customerWrite&&!readonly" class="commerce-actions"><button v-if="!snapshot.contractLinked" class="btn primary" :disabled="busy" @click="dialog='';emit('contract',snapshot.id)">以此批准报价建立合同</button><span v-else class="commerce-muted">该批准版本已用于合同，后续调整请创建新报价并重新审批。</span></div><h3>审批记录</h3><p v-if="!approvalRows.length" class="commerce-muted">暂无审批记录。旧版待审批报价需先撤回，再指定审批人重新提交。</p><ul class="commerce-history"><li v-for="a in approvalRows" :key="a.id"><button class="text-button" :disabled="busy" @click="selectVersion(a.submittedVersion)">提交 v{{a.submittedVersion}}</button><span>{{statusNames[a.status]}} · {{money(a.amountCents)}} · {{a.submittedNameSnapshot}} → {{a.approverNameSnapshot}}<small>{{date(a.createdAt)}}{{a.decidedAt?' · 处理于 '+date(a.decidedAt):''}}</small><small v-if="a.reason">原因／意见：{{a.reason}}</small></span></li></ul><div class="commerce-inline"><button :disabled="busy||approvalPage<=1" @click="approvalTurn(-1)">上一页</button><small>审批第 {{approvalPage}} 页 · 共 {{approvalTotal}} 次</small><button :disabled="busy||approvalPage*10>=approvalTotal" @click="approvalTurn(1)">下一页</button></div><h3>版本记录</h3><ul class="commerce-history"><li v-for="h in history" :key="h.id"><button class="text-button" :disabled="busy" @click="selectVersion(h.businessVersion)">查看 v{{h.businessVersion}}</button><span>{{actionNames[h.action]}} · {{h.actorName}} · {{date(h.createdAt)}}</span></li></ul><div class="commerce-inline"><button :disabled="busy||historyPage<=1" @click="historyTurn(-1)">上一页</button><small>第 {{historyPage}} 页 · 共 {{historyTotal}} 个版本</small><button :disabled="busy||historyPage*20>=historyTotal" @click="historyTurn(1)">下一页</button><button v-if="historical" class="text-button" :disabled="busy" @click="selectVersion(selected!.version)">返回当前版本</button></div><p class="commerce-muted">审批针对提交时的报价版本和金额。驳回或转回草稿后需要重新提交；合同与回款在后续阶段接入。</p><section v-if="!historical&&selected?.canManage&&!readonly&&['DRAFT','REJECTED'].includes(snapshot.status)" class="commerce-catalog"><h3>提交审批</h3><div class="commerce-inline"><input v-model="approverQuery" maxlength="100" aria-label="搜索审批销售经理" placeholder="搜索审批销售经理" @keydown.enter="approverSearch"/><button class="btn secondary" :disabled="busy" @click="approverSearch">查找</button></div><label>指定审批人<select v-model="approverId" aria-label="指定审批人"><option value="">请选择另一位销售经理</option><option v-for="m in approvers" :key="m.id" :value="m.id">{{m.name}}</option></select></label><div class="commerce-inline"><button :disabled="busy||approverPage<=1" @click="approverTurn(-1)">上一页</button><small>第 {{approverPage}} 页 · 共 {{approverTotal}} 位</small><button :disabled="busy||approverPage*20>=approverTotal" @click="approverTurn(1)">下一页</button></div><p v-if="!approverTotal" class="commerce-muted">没有可选审批人。企业管理员需在「组织成员」配置另一位销售经理，完成首次改密，并在「角色权限」授予报价审批及相关资料读取权限。</p></section><label v-if="!historical&&selected?.canApprove&&!readonly" class="commerce-void">审批意见（驳回必填）<textarea v-model="decisionReason" rows="3" maxlength="500"/></label><label v-if="!historical&&selected?.canManage&&snapshot.status==='APPROVED'&&!readonly" class="commerce-void">重新修改原因<input v-model="changeReason" maxlength="500" placeholder="转回草稿后需要重新审批"/></label><label v-if="!historical&&selected?.canManage&&snapshot.status!=='VOID'" class="commerce-void">作废原因<input v-model="voidReason" maxlength="500" placeholder="填写原因后可作废当前报价"/></label></div><footer><button class="btn secondary" :disabled="busy" @click="dialog=''">关闭</button><button v-if="access.pdfExport" class="btn secondary" :disabled="busy" @click="exportPdf">下载当前查看版本 PDF</button><template v-if="!historical&&selected?.canManage&&!readonly"><button v-if="['DRAFT','REJECTED'].includes(snapshot.status)" class="btn primary" :disabled="busy||!approverId" @click="transition('submit')">提交审批</button><button v-if="snapshot.status==='SUBMITTED'" class="btn secondary" :disabled="busy" @click="transition('withdraw')">撤回草稿</button><button v-if="snapshot.status==='APPROVED'" class="btn secondary" :disabled="busy||!changeReason.trim()" @click="transition('revise')">转回草稿修改</button><button v-if="snapshot.status!=='VOID'" class="text-button" :disabled="busy||!voidReason.trim()" @click="transition('void')">作废报价</button></template><template v-if="!historical&&selected?.canApprove&&!readonly"><button class="btn primary" :disabled="busy" @click="decide('approve')">批准当前版本</button><button class="btn secondary" :disabled="busy||!decisionReason.trim()" @click="decide('reject')">驳回并记录原因</button></template></footer></template></section></div></Teleport>
 </section>
</template>
